<?php

declare(strict_types=1);
namespace MyInvoice\Tests\Integration\Tax;
use MyInvoice\Bootstrap;
use MyInvoice\Infrastructure\Config\Config;
use MyInvoice\Infrastructure\Database\Connection;
use MyInvoice\Repository\{AccountingPeriodRepository,NonprofitTaxSourceRepository};
use MyInvoice\Service\Accounting\PostingService;
use MyInvoice\Service\Anonymization\DatabaseCloner;
use MyInvoice\Service\Tax\Nonprofit\{NonprofitLegalProfileService,NonprofitTaxAssessmentService,NonprofitTaxAssessmentException};
use MyInvoice\Tests\Support\{FundingFixture,OwnedTestDatabaseCleanup};
use PDO;
use PHPUnit\Framework\TestCase;
final class NonprofitSvjSnapshotBoundaryTest extends TestCase
{
    use FundingFixture {setUp as private fixtureSetUp;tearDown as private fixtureTearDown;}
    private string|false $priorDatabase;private string $owned;private PDO $server;
    protected function setUp():void
    {
        $this->priorDatabase=getenv('MYINVOICE_DB_NAME');$config=Config::load(Bootstrap::rootDir());self::assertStringEndsWith('_test',$config->get('db.name'));self::assertContains($config->get('db.host'),['localhost','127.0.0.1','::1']);$this->owned='myucto_svj_boundary_'.bin2hex(random_bytes(5)).'_test';
        $this->server=new PDO('mysql:host='.$config->get('db.host').';port='.$config->get('db.port',3306).';charset=utf8mb4',$config->get('db.user'),$config->get('db.pass',''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$cloner=new DatabaseCloner($this->server);$plan=$cloner->plan($config->get('db.name'));$cloner->copyTables($plan,$this->owned,static function():void{});$cloner->finalize($plan,$this->owned);putenv('MYINVOICE_DB_NAME='.$this->owned);Connection::withoutSharedTestConnection(fn()=>$this->fixtureSetUp());
    }
    protected function tearDown():void
    {if(isset($this->db)){$this->fixtureTearDown();$this->db->close();}putenv($this->priorDatabase===false?'MYINVOICE_DB_NAME':'MYINVOICE_DB_NAME='.$this->priorDatabase);if(isset($this->owned,$this->server))OwnedTestDatabaseCleanup::drop($this->server,$this->owned,[$this->owned]);}
    private function assessment(array $snapshot):array
    {
        $a=['profile'=>['kind'=>'svj','evidence'=>'Synthetic owner legal position'],'activities'=>[],'decisions'=>[]];foreach($snapshot['sources']as$row){$a['activities'][$row['activity_kind_id']]=['evidence'=>'Synthetic measured purpose'];$a['decisions'][$row['id']]=$row['kind']==='expense'?['title'=>'excluded_cost','deductible_cents'=>0,'legal_basis'=>'zdp_25_1i','evidence'=>'Synthetic direct management cost']:['title'=>'svj_management_payment','evidence'=>'Synthetic proved owner contribution'];}return$a;
    }
    public function testCommittedReadPreviewConfirmCasAndCurrentReadAfterStaleRr():void
    {
        $this->fundingIssue();$cost=$this->fundingCost('2026-09-01','518.200','10000.00');$this->fundingApply($this->fundingDraw('2026-09-01','administration','500000',$cost,'issued'),'boundary-first');$s=$this->f['supplier'];$actor=$this->f['actor'];$period=(int)$this->container->get(AccountingPeriodRepository::class)->findByYear($s,2026)['id'];
        (new NonprofitLegalProfileService($this->db))->confirm($s,$period,['profile'=>['kind'=>'svj','entity_type'=>'svj','main_activity_nonbusiness'=>true,'evidence'=>'Synthetic signed SVJ articles','legal_basis'=>'zdp_17a_18_2f'],'expected_revision'=>0,'reason'=>'Synthetic legal review','idempotency_key'=>'boundary-legal'],$actor);$this->db->pdo()->commit();self::assertFalse($this->db->pdo()->inTransaction());
        $source=$this->container->get(NonprofitTaxSourceRepository::class);$tax=$this->container->get(NonprofitTaxAssessmentService::class);$raw=$source->snapshot($s,$period);self::assertFalse($this->db->pdo()->inTransaction());$row=array_column($raw['sources'],null,'line_id')[$cost];self::assertSame(1000000,$row['svj_owner_facts']['related_out_of_scope_cents']??null);self::assertSame([],$raw['findings']);self::assertSame($raw,$tax->read($s,$period)['snapshot']);
        $counts=$this->counts();$a=$this->assessment($raw);$preview=$tax->preview($s,$period,$a);self::assertSame($counts,$this->counts());self::assertFalse($this->db->pdo()->inTransaction());$receipt=$tax->confirm($s,$period,$a,$preview['snapshot']['input_hash'],'Synthetic explicit legal confirmation','boundary-confirm',$actor);self::assertSame(0,$receipt['result']['assessed_result_cents']);self::assertSame($receipt,$tax->confirm($s,$period,$a,$preview['snapshot']['input_hash'],'Synthetic explicit legal confirmation','boundary-confirm',$actor));self::assertFalse($this->db->pdo()->inTransaction());
        $this->db->pdo()->beginTransaction();(new \MyInvoice\Service\Property\Payments\PaymentLocks($this->db))->acquire($s);$q=$this->db->pdo()->prepare('SELECT entry_id FROM journal_entry_lines WHERE supplier_id=? AND id=?');$q->execute([$s,$cost]);$proof=(new \MyInvoice\Service\Property\Payments\PaymentJournalProof($this->db))->snapshot($s,(int)$q->fetchColumn(),false);$costLine=array_column($proof['lines'],null,'id')[$cost];$this->db->pdo()->commit();
        $this->db->pdo()->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->pdo()->beginTransaction();$old=(int)$this->db->pdo()->query('SELECT COUNT(*) FROM journal_entries')->fetchColumn();[$other,$posting]=Connection::withoutSharedTestConnection(static function():array{$c=Bootstrap::buildContainer();return[$c,$c->get(PostingService::class)];});$entry=$posting->postDocument($s,'manual',null,[['account_code'=>'518','side'=>'debit','amount'=>'100.00','dimensions'=>$costLine['dimensions'],'dimension_origins'=>array_fill_keys(array_keys($costLine['dimensions']),['origin'=>'explicit','ref'=>null])],['account_code'=>'321','side'=>'credit','amount'=>'100.00']],['entry_date'=>'2026-09-02','posted_by'=>$actor]);self::assertSame($old,(int)$this->db->pdo()->query('SELECT COUNT(*) FROM journal_entries')->fetchColumn());try{$fresh=$source->snapshot($s,$period);}catch(\PDOException $e){self::assertSame(1020,(int)$e->errorInfo[1]);self::assertFalse($this->db->pdo()->inTransaction());$fresh=$source->snapshot($s,$period);}self::assertContains($entry,array_column($fresh['ledger'],'entry_id'));self::assertNotSame($raw['input_hash'],$fresh['input_hash']);if($this->db->pdo()->inTransaction())$this->db->pdo()->rollBack();$other->get(Connection::class)->close();
        try{$tax->confirm($s,$period,$a,$raw['input_hash'],'Synthetic stale confirmation','boundary-stale',$actor,$receipt['id']);self::fail('Stale source must be rejected');}catch(NonprofitTaxAssessmentException $e){self::assertSame('nonprofit_tax_sources_changed',$e->errorCode);}self::assertCount(1,$tax->history($s,$period));self::assertFalse($this->db->pdo()->inTransaction());
        $current=$source->snapshot($s,$period);$this->db->pdo()->prepare("UPDATE accounting_periods SET status='closed' WHERE supplier_id=? AND id=?")->execute([$s,$period]);self::assertSame($current,$source->snapshot($s,$period));self::assertFalse($this->db->pdo()->inTransaction());
    }
    public function testSameYearReverseThenNativeReplaceReportsTheActualS9OwnerBoundary():void
    {
        $this->fundingIssue();$cost=$this->fundingCost('2026-09-01','518.200','10000.00');$op=$this->fundingApply($this->fundingDraw('2026-09-01','administration','500000',$cost,'issued'),'replace-original');$request=$this->fundingRequest('reverse','2026-10-01')+['operation_id'=>$op['id']];unset($request['amount_cents']);$reverse=$this->fundingApply($request,'replace-reverse');$s=$this->f['supplier'];$period=(int)$this->container->get(AccountingPeriodRepository::class)->findByYear($s,2026)['id'];$actor=$this->f['actor'];
        (new NonprofitLegalProfileService($this->db))->confirm($s,$period,['profile'=>['kind'=>'svj','entity_type'=>'svj','main_activity_nonbusiness'=>true,'evidence'=>'Synthetic signed SVJ articles','legal_basis'=>'zdp_17a_18_2f'],'expected_revision'=>0,'reason'=>'Synthetic legal review','idempotency_key'=>'replace-legal'],$actor);
        $q=$this->db->pdo()->prepare('SELECT e.* FROM journal_entries e JOIN journal_entry_lines l ON l.supplier_id=e.supplier_id AND l.entry_id=e.id WHERE l.supplier_id=? AND l.id=? FOR UPDATE');$q->execute([$s,$cost]);$header=$q->fetch(PDO::FETCH_ASSOC);$proof=(new \MyInvoice\Service\Property\Payments\PaymentJournalProof($this->db))->current($s,(int)$header['id']);$lines=$proof['lines'];$accounts=new \MyInvoice\Repository\ChartOfAccountsRepository($this->db);foreach($lines as&$line)$line['account_id']=$accounts->findByCode($s,$line['account_code'])['id'];unset($line);
        self::assertFalse((new \MyInvoice\Repository\Property\Funds\FundingRepository($this->db))->operation($s,$op['id'])['active']);
        try{\MyInvoice\Service\Property\Funds\FundingUseGuard::assertEntriesMutable($this->db,$s,[(int)$header['id']]);self::fail('Exact S9 immutable source claim must remain');}catch(\MyInvoice\Service\Property\Funds\FundingException $e){self::assertSame('property_funding_source_owned',$e->errorCode);}
        try{$this->container->get(\MyInvoice\Repository\JournalEntryRepository::class)->replace((int)$header['id'],$header,$lines);self::fail('Current S9 immutable claim must reject JRreplace even after reversal');}catch(\MyInvoice\Service\Accounting\PostingException $e){self::assertSame('property_payment_source_immutable',$e->errorCode);self::assertSame(409,$e->httpStatus);}
        self::assertSame($proof,(new \MyInvoice\Service\Property\Payments\PaymentJournalProof($this->db))->current($s,(int)$header['id']));$this->db->pdo()->commit();$tax=$this->container->get(NonprofitTaxAssessmentService::class);$snapshot=$tax->read($s,$period)['snapshot'];self::assertFalse($this->db->pdo()->inTransaction());$row=array_column($snapshot['sources'],null,'line_id')[$cost];self::assertSame(1000000,$row['svj_owner_facts']['related_out_of_scope_cents']);self::assertSame(0,$row['svj_owner_facts']['covered_cost_cents']);$preview=$tax->preview($s,$period,$this->assessment($snapshot));self::assertSame(0,$preview['result']['assessed_result_cents']);$income=array_filter($preview['result']['rows'],static fn(array $r):bool=>$r['kind']==='revenue');self::assertNotEmpty($income);self::assertSame(0,array_sum(array_column($income,'amount_cents')));self::assertFalse($this->db->pdo()->inTransaction());
    }
    public function testActualNativeSeparatedTaxablePurposeKeepsOnlyItsOwnCostDeductible():void
    {
        $this->fundingIssue();$management=$this->fundingCost('2026-09-01','518.200','7000.00');$this->fundingApply($this->fundingDraw('2026-09-01','administration','500000',$management,'issued'),'mixed-management');$accounts=new \MyInvoice\Repository\ChartOfAccountsRepository($this->db);$accounts->setTaxDeductibility($this->f['supplier'],(int)$accounts->findByCode($this->f['supplier'],'518')['id'],'deductible','2026-01-01');$taxable=$this->fundingCost('2026-09-01','518','3000.00');$s=$this->f['supplier'];$actor=$this->f['actor'];$q=$this->db->pdo()->prepare('SELECT entry_id FROM journal_entry_lines WHERE supplier_id=? AND id=?');$q->execute([$s,$taxable]);$proof=(new \MyInvoice\Service\Property\Payments\PaymentJournalProof($this->db))->current($s,(int)$q->fetchColumn());$line=array_column($proof['lines'],null,'id')[$taxable];$this->container->get(PostingService::class)->postDocument($s,'manual',null,[['account_code'=>'221','side'=>'debit','amount'=>'1500.00'],['account_code'=>'682','side'=>'credit','amount'=>'1500.00','dimensions'=>$line['dimensions'],'dimension_origins'=>array_fill_keys(array_keys($line['dimensions']),['origin'=>'explicit','ref'=>null])]],['entry_date'=>'2026-09-01','posted_by'=>$actor]);$period=(int)$this->container->get(AccountingPeriodRepository::class)->findByYear($s,2026)['id'];
        (new NonprofitLegalProfileService($this->db))->confirm($s,$period,['profile'=>['kind'=>'svj','entity_type'=>'svj','main_activity_nonbusiness'=>true,'evidence'=>'Synthetic signed SVJ articles','legal_basis'=>'zdp_17a_18_2f'],'expected_revision'=>0,'reason'=>'Synthetic legal review','idempotency_key'=>'mixed-legal'],$actor);$this->db->pdo()->commit();$tax=$this->container->get(NonprofitTaxAssessmentService::class);$snapshot=$tax->read($s,$period)['snapshot'];$a=$this->assessment($snapshot);$rows=array_column($snapshot['sources'],null,'line_id');self::assertArrayNotHasKey('svj_owner_facts',$rows[$taxable]);self::assertNotSame($rows[$management]['activity_kind_id'],$rows[$taxable]['activity_kind_id']);$a['decisions']['line:'.$taxable]=['title'=>'cost','deductible_cents'=>300000,'legal_basis'=>'zdp_24_1','evidence'=>'Synthetic separately invoiced work on own taxable third-party income'];
        foreach($snapshot['sources']as$row)if($row['kind']==='revenue'&&!isset($row['svj_owner_facts']))$a['decisions'][$row['id']]=['title'=>'gift','evidence'=>'Synthetic received third-party private gift, not owner contribution','facts'=>['claim_exemption'=>false,'income_treatment'=>'separate_taxable_income','income_attribution_evidence'=>'Synthetic separate taxable SVJ gift and measured related agenda']];
        $preview=$tax->preview($s,$period,$a);self::assertSame(-150000,$preview['result']['assessed_result_cents']);$receipt=$tax->confirm($s,$period,$a,$preview['snapshot']['input_hash'],'Synthetic separately documented mixed purposes','mixed-confirm',$actor);$actual=array_column($receipt['result']['rows'],null,'line_id');self::assertSame(0,$actual[$management]['deductible_cents']);self::assertSame(300000,$actual[$taxable]['deductible_cents']);self::assertSame(0,$actual[$management]['funded_excluded_cents']);self::assertSame(-150000,$receipt['result']['assessed_result_cents']);self::assertFalse($this->db->pdo()->inTransaction());
    }
    private function counts():array{return[(int)$this->db->pdo()->query('SELECT COUNT(*) FROM journal_entries')->fetchColumn(),(int)$this->db->pdo()->query('SELECT COUNT(*) FROM nonprofit_tax_assessments')->fetchColumn()];}
}
